let item = {};
try {
  item = $input.first().json || {};
} catch (e) {
  try {
    item = $json || {};
  } catch (e2) {}
}

let usdAmount = parseFloat(item.monto_usd || item.usd || 0);
let months = parseInt(item.meses || item.mes || 0);

// If query string is passed (e.g. "3 meses", "3", "24", "1 mes", "12 meses")
const query = (item.query || '').toString().toLowerCase();
if (!months && query) {
  if (query.includes('12') || query.includes('año') || query.includes('ano') || query.includes('84')) {
    months = 12;
  } else if (query.includes('6') || query.includes('48')) {
    months = 6;
  } else if (query.includes('3') || query.includes('24')) {
    months = 3;
  } else if (query.includes('1') || query.includes('8')) {
    months = 1;
  }
}

if (!usdAmount && months) {
  if (months === 1) usdAmount = 8;
  else if (months === 3) usdAmount = 24;
  else if (months === 6) usdAmount = 48;
  else if (months === 12) usdAmount = 84;
}

if (!usdAmount) {
  usdAmount = 8; // Default 1 month
}

// 1. Fetch Binance P2P (Live benchmark rate for USDT to Bolívares / Pago Móvil)
// We query tradeType: 'BUY' to capture the active market price in Binance P2P (~938+ Bs)
let binanceRate = 0;
try {
  const bRes = await fetch('https://p2p.binance.com/bapi/c2c/v2/friendly/c2c/adv/search', {
    method: 'POST',
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      asset: 'USDT',
      fiat: 'VES',
      merchantCheck: false,
      page: 1,
      payTypes: ['PagoMovil'],
      publisherType: null,
      rows: 20,
      tradeType: 'BUY'
    })
  });
  const bData = await bRes.json();
  const ads = bData.data || [];

  // Filter out any abnormal outliers (must be > 800)
  const validPrices = ads
    .map(a => parseFloat(a.adv?.price || 0))
    .filter(p => p > 800);

  if (validPrices.length > 0) {
    // In tradeType: 'BUY', top ads list the active best market price (~938.30 Bs)
    binanceRate = validPrices[0];
  }
} catch (e) {}

// Fallback: If BUY failed, try SELL or DolarAPI
if (!binanceRate) {
  try {
    const bRes2 = await fetch('https://p2p.binance.com/bapi/c2c/v2/friendly/c2c/adv/search', {
      method: 'POST',
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        asset: 'USDT',
        fiat: 'VES',
        merchantCheck: false,
        page: 1,
        payTypes: ['PagoMovil'],
        publisherType: null,
        rows: 10,
        tradeType: 'SELL'
      })
    });
    const bData2 = await bRes2.json();
    const ads2 = bData2.data || [];
    const validPrices2 = ads2.map(a => parseFloat(a.adv?.price || 0)).filter(p => p > 800);
    if (validPrices2.length > 0) {
      binanceRate = Math.max(...validPrices2);
    }
  } catch (e) {}
}

let paraleloRate = 0;
if (!binanceRate) {
  try {
    const pRes = await fetch('https://ve.dolarapi.com/v1/dolares/paralelo', {
      headers: { 'User-Agent': 'Mozilla/5.0' }
    });
    const pData = await pRes.json();
    paraleloRate = parseFloat(pData.promedio || 0);
  } catch (e) {}
}

const effectiveRate = binanceRate || paraleloRate || 938.30;
const totalBs = (usdAmount * effectiveRate).toFixed(2);

return [{
  json: {
    tasa_del_dia: effectiveRate.toFixed(2),
    monto_usd: usdAmount,
    meses: months || 1,
    total_bs: totalBs,
    fuente_tasa: binanceRate ? 'Binance P2P Pago Móvil' : 'DolarAPI Paralelo',
    banco: 'Bancamiga',
    telefono: '04246861135',
    rif: 'J405259221',
    beneficiario: 'ArialStore C.A.',
    qr_url: 'https://raw.githubusercontent.com/totaltvusa/images/main/Arialstorepm.jpeg',
    resumen_precios_bs: {
      plan_1_mes: (8 * effectiveRate).toFixed(2) + ' Bs ($8)',
      plan_3_meses: (24 * effectiveRate).toFixed(2) + ' Bs ($24)',
      plan_6_meses: (48 * effectiveRate).toFixed(2) + ' Bs ($48)',
      plan_12_meses: (84 * effectiveRate).toFixed(2) + ' Bs ($84)'
    }
  }
}];
